update events set website_url='https://www.dokolamtb.cz/',description='Bikepackingový závod bez podpory 11.–13. 6. 2027 v Sedlejově u Telče. Pořadatel oznamuje tři trasy přibližně 400, 200 a 100 km, se startem v pátek i v sobotu. Přesný rozpis startů pro jednotlivé trasy bude upřesněn.',updated_at=now() where id='532e5fd5-a1eb-4dc8-a4a4-2a4c66908641';
