insert into event_overrides(event_id,fields,locked_fields,updated_by) values('38af09e7-a920-47b5-8b75-e2d17f64d02a','{"name":"UCI MTB World Cup – Nové Město na Moravě 2027","start_date":"2027-05-21","end_date":"2027-05-23","location_id":"bfa627cb-a5eb-45e7-a761-e5141a7487c6","disciplines":["xco","xcc"],"formats":["xco","xcc"],"status":"scheduled","visibility":"public","event_type":"race","website_url":"https://www.mtbnmnm.com/","registration_url":null,"registration_opens_at":null,"regulations_url":null,"age_categories":["junior","u23","elite"],"age_confidence":"previous","description":"WHOOP UCI Mountain Bike World Series 2027, 1. kolo. Disciplíny: XCO, XCC. Termín víkendu je potvrzený oficiálním kalendářem; rozpis jednotlivých závodů a registrace pro rok 2027 zatím nejsou potvrzené. Věkové filtry jsou orientačně převzaté z ročníku 2026; nejde o ověřený úplný rozpis 2027. UCI samostatně eviduje doprovodnou UCI XCO Junior Series mužů a žen (21.–23. 5. 2027, UCI 80464); nejde o juniorský Světový pohár XCO. Pořadatel uvádí širší termín akce 20.–23. 5. 2027, ale podrobný program na webu je stále pro rok 2026. Náplň 20. 5. 2027 a juniorské XCC pro rok 2027 zatím nejsou potvrzené; světový pohár ukládáme od 21. 5. podle oficiálního kalendáře.","series_id":"641843a4-5761-4533-9b46-e61a1e4da868"}'::jsonb,array['name','start_date','end_date','location_id','disciplines','formats','status','visibility','event_type','website_url','registration_url','registration_opens_at','regulations_url','age_categories','age_confidence','description','series_id']::text[],'official Czech 2027 discoveries review 2026-10-31') on conflict(event_id) do update set fields=event_overrides.fields || excluded.fields,locked_fields=array(select distinct unnest(event_overrides.locked_fields || excluded.locked_fields)),updated_by=excluded.updated_by,updated_at=now();
